.account-info {
  background-color: $highlight;
  border-radius: rem-calc(3);
  font-size: rem-calc(16);
  font-weight: normal;
  margin-bottom: $line-height;
  padding: calc($line-height / 2);

  strong {
    font-size: rem-calc(18);
  }
}

.extra-info {
  background: #fafafa;
  border-bottom-left-radius: rem-calc(6);
  border-bottom-right-radius: rem-calc(6);
  border-top: 2px solid;
  font-size: $small-font-size;
  padding: calc($line-height / 2);
}

.admin-budget-investment-info {
  background: $highlight-soft;
  border: 2px solid $highlight;
  border-radius: rem-calc(4);
  margin-bottom: $line-height;
  padding: calc($line-height / 2);

  p {
    font-size: $small-font-size;
    margin-bottom: 0;
  }
}

.investment-projects-summary {

  th,
  td {
    text-align: center;

    &:first-child {
      font-weight: bold;
      text-align: left;
    }

    &:last-child {
      font-weight: bold;
    }
  }

  tr {
    &:nth-child(even) td:last-child {
      background: $success-border;
    }

    &:nth-child(odd) td:last-child {
      background: $success-bg;
    }
  }
}

.admin-content > header {
  align-items: flex-start;
  display: flex;
  flex-wrap: wrap;

  a,
  button,
  form {
    margin-#{$global-left}: auto;
  }

  a,
  button {
    &:not(.delete) {
      @include regular-button;
      margin-#{$global-left}: auto;
    }
  }
}

.admin-content .select-heading {

  a {
    color: inherit;
    display: block;

    &.is-active {
      @include brand-color;
      font-weight: bold;
      text-decoration: underline;
    }
  }
}

.management-list {
  max-width: rem-calc(1200);
}

