{
  "returncode": 0,
  "output": "@use "sass:color";

// Table of Contents
//
// 01. Votes and supports
// 02. New participation
// 03. Show participation
// 04. List participation
// 05. Featured
// 06. Budgets
// 07. Proposals successful
// 08. Polls
// 09. Polls results and stats
//

// 01. Votes and supports
// ----------------------

@mixin supports {
  padding: $line-height 0;
  position: relative;

  .progress {
    background: color.adjust($proposals, $lightness: 35%);
    border: 1px solid color.adjust($proposals, $lightness: 35%);
    height: rem-calc(14);
    position: relative;

    .meter {
      background: $proposals;
      border-radius: 0;
      border-bottom-right-radius: rem-calc(3);
      border-top-right-radius: rem-calc(3);
      display: block;
      height: calc($line-height / 2);
    }
  }

  .percentage {
    font-size: $tiny-font-size;
    position: absolute;
    right: 6px;
    top: -2px;
    vertical-align: top;
  }

  abbr {
    color: $text-medium;

    &[title] {
      border-bottom: 0;
    }
  }

  .button-support {
